# Name: kpod
# Author: Qingshan
# Icon: data:image/png;base64,
# DontUseFBInk
# KeepLibraryEntry

# Keep the launcher alive until KPM hands control to the WAF.
setsid sh -c 'exec /var/local/kmc/bin/kpm launch kpod' </dev/null >/dev/null 2>&1 &
wait $! || exit $?

# appmgrd start returns before the WAF becomes active.
_i=0
while [ "$_i" -lt 15 ]; do
    [ "$(lipc-get-prop com.lab126.appmgrd activeApp 2>/dev/null)" = "dev.qingshan.kpod" ] && break
    sleep 1
    _i=$((_i + 1))
done
